// scripts/task158-debug-applier.ts
import fs from "node:fs";
async function main() {
  const env = {};
  for (const line of fs.readFileSync("/tmp/my-project/.env.production.local", "utf8").split("\n")) {
    const m = /^([A-Z0-9_]+)=(.*)$/.exec(line.trim());
    if (m) env[m[1]] = m[2].replace(/^["']|["']$/g, "");
  }
  for (const [k, v] of Object.entries(env)) {
    if (/^(DATABASE_URL|ETIMEOFFICE_|CRON_SECRET|PLATFORM_)/.test(k)) process.env[k] = v;
  }
  const { getDbForTenantById: getDbForTenantById2, getPlatformDb: getPlatformDb2 } = await Promise.resolve().then(() => (init_tenant_db(), tenant_db_exports));
  const platformDb = getPlatformDb2();
  const tenant = await platformDb.tenant.findFirst({ where: { slug: "marqaitechgroup" }, select: { id: true } });
  const db2 = await getDbForTenantById2(tenant.id);
  const reqRow = await db2.employeeUpdateRequest.findUnique({
    where: { id: "cmvqhcy7e000h07kwln00n23d" },
    select: { id: true, fieldName: true, newValue: true, oldValue: true, employeeId: true }
  });
  console.log("REQUEST:", reqRow.fieldName, "newValue:", reqRow.newValue?.slice(0, 200));
  const { applyProfileSectionChange: applyProfileSectionChange2 } = await Promise.resolve().then(() => (init_employee_update_request(), employee_update_request_exports));
  try {
    const r = await applyProfileSectionChange2(db2, reqRow.employeeId, reqRow.fieldName, reqRow.newValue);
    console.log("APPLY OK:", JSON.stringify(r));
    await db2.employeeUpdateRequest.update({ where: { id: reqRow.id }, data: { status: "applied", appliedAt: /* @__PURE__ */ new Date() } });
    console.log("REQUEST marked applied");
  } catch (e) {
    console.error("APPLY THREW:", e?.message);
    console.error(e?.stack?.split("\n").slice(0, 6).join("\n"));
  }
  const empRaw = await db2.$queryRawUnsafe(`SELECT "bloodGroup", "emergencyMedicalCondition" FROM "Employee" WHERE "id" = $1`, reqRow.employeeId);
  console.log("EMPLOYEE NOW (raw):", JSON.stringify(empRaw?.[0]));
  await db2.$disconnect();
}
main().catch((e) => {
  console.error("RUNNER FAILED:", e?.message);
  process.exit(1);
});
